15	#ifndef XLS_PASSES_BDD_QUERY_ENGINE_H_
16	#define XLS_PASSES_BDD_QUERY_ENGINE_H_
17	
18	#include <cstdint>
19	#include <functional>
20	#include <memory>
21	#include <optional>
22	#include <utility>
23	#include <variant>
24	#include <vector>
25	
26	#include "absl/container/btree_map.h"
27	#include "absl/container/btree_set.h"
28	#include "absl/container/flat_hash_map.h"
29	#include "absl/log/check.h"
30	#include "absl/types/span.h"
31	#include "xls/data_structures/binary_decision_diagram.h"
32	#include "xls/data_structures/leaf_type_tree.h"
33	#include "xls/ir/bits.h"
34	#include "xls/ir/node.h"
35	#include "xls/ir/ternary.h"
36	#include "xls/ir/value.h"
37	#include "xls/passes/bdd_evaluator.h"
38	#include "xls/passes/lazy_query_engine.h"
39	#include "xls/passes/predicate_state.h"
40	#include "xls/passes/query_engine.h"
41	
42	namespace xls {
43	
44	// A query engine which uses binary decision diagrams (BDDs) to analyze an XLS
45	// function. BDDs provide sharp analysis of bits values and relationships
46	// between bit values in the function (relative to ternary abstract evaluation).
47	// The downside is that BDDs can be slow in general and exponentially slow in
48	// particular for some operations such as arithmetic and comparison
49	// operations. For this reason, these operations are generally excluded from the
50	// analysis.
51	class BddQueryEngine
52	    : public LazyQueryEngine<std::vector<SaturatingBddNodeIndex>> {
53	 private:
54	  using Base = LazyQueryEngine<std::vector<SaturatingBddNodeIndex>>;
55	  using BddVector = std::vector<SaturatingBddNodeIndex>;
56	  using BddTree = LeafTypeTree<BddVector>;
57	  using BddTreeView = LeafTypeTreeView<BddVector>;
58	  using SharedBddTree = SharedLeafTypeTree<BddVector>;
59	
60	 public:
61	  // The suggested default limit on the number of paths from a BDD node to the
62	  // BDD terminal nodes 0 and 1. If a BDD node associated with a particular bit
63	  // in the function ({Node*, bit index} pair) exceeds this value the bit's
64	  // representation in the BDD is replaced with a new BDD variable. This
65	  // provides a mechanism for limiting the growth of the BDD.
66	  static constexpr int64_t kDefaultPathLimit = 1024;
67	
68	  // Calculating if at most one bit is true is quadratic so we limit it to
69	  // values this large or smaller.
70	  static constexpr int64_t kOneHotSizeLimit = 300;
71	
72	  // Returns an instance of the recommended default BddQueryEngine, using
73	  // kDefaultPathLimit and filtering to operate only on nodes that satisfy
74	  // IsCheapForBdds.
75	  static std::unique_ptr<BddQueryEngine> MakeDefault() {
76	    return std::make_unique<BddQueryEngine>(kDefaultPathLimit);
77	  }
78	
79	  // `path_limit` is the maximum number of paths from the BDD node to the
80	  // terminals 0 and 1 to allow for a BDD expression before truncating it.
81	  // `node_filter` is an optional function which filters the nodes to be
82	  // evaluated. If this function returns false for a node then the node will not
83	  // be evaluated using BDDs. The node's bits will be new variables in the BDD
84	  // for which no information is known. If `node_filter` returns true, the node
85	  // still might *not* be evaluated because some kinds of nodes are never
86	  // evaluated for various reasons including computation expense.
87	  explicit BddQueryEngine(int64_t path_limit = 0,
88	                          std::optional<std::function<bool(const Node*)>>
89	                              node_filter = std::nullopt)
90	      : path_limit_(path_limit),
91	        node_filter_(node_filter),
92	        bdd_(std::make_unique<BinaryDecisionDiagram>(
93	            path_limit > 0 ? path_limit
94	                           : BinaryDecisionDiagram::kDefaultMaxPaths)),
95	        evaluator_(
96	            std::make_unique<SaturatingBddEvaluator>(path_limit, bdd_.get())) {}
97	
98	  int64_t path_limit() const { return path_limit_; }
99	
100	  std::optional<SharedLeafTypeTree<TernaryVector>> GetTernary(
101	      Node* node) const override;
102	
103	  std::unique_ptr<QueryEngine> SpecializeGivenPredicate(
104	      const absl::btree_set<PredicateState>& state) const override;
105	  std::unique_ptr<QueryEngine> SpecializeGiven(
106	      const absl::btree_map<Node*, ValueKnowledge, Node::NodeIdLessThan>&
107	          givens) const override;
108	
109	  bool AtMostOneTrue(absl::Span<TreeBitLocation const> bits) const override;
110	  bool AtLeastOneTrue(absl::Span<TreeBitLocation const> bits) const override;
111	  bool Implies(const TreeBitLocation& a,
112	               const TreeBitLocation& b) const override;
113	  std::optional<Bits> ImpliedNodeValue(
114	      absl::Span<const std::pair<TreeBitLocation, bool>> predicate_bit_values,
115	      Node* node) const override;
116	  std::optional<TernaryVector> ImpliedNodeTernary(
117	      absl::Span<const std::pair<TreeBitLocation, bool>> predicate_bit_values,
118	      Node* node) const override;
119	  bool KnownEquals(const TreeBitLocation& a,
120	                   const TreeBitLocation& b) const override;
121	  bool KnownNotEquals(const TreeBitLocation& a,
122	                      const TreeBitLocation& b) const override;
123	
124	  bool IsAllZeros(Node* n) const override { return QueryEngine::IsAllZeros(n); }
125	  bool IsAllOnes(Node* n) const override { return QueryEngine::IsAllOnes(n); }
126	  bool IsFullyKnown(Node* n) const override {
127	    return QueryEngine::IsFullyKnown(n);
128	  }
129	  bool IsFullyUnconstrained(Node* node) const;
130	  bool IsKnown(const TreeBitLocation& bit) const override {
131	    return KnownValue(bit).has_value();
132	  }
133	  std::optional<bool> KnownValue(const TreeBitLocation& bit) const override;
134	  std::optional<Value> KnownValue(Node* node) const override {
135	    return QueryEngine::KnownValue(node);
136	  }
137	
138	  // Returns the underlying BDD. This method is const, but queries on a BDD
139	  // generally mutate the object. We sneakily avoid conflicts with C++ const
140	  // because the BDD is only held indirectly via pointers.
141	  // TODO(meheff): Enable queries on a BDD without mutating the BDD itself.
142	  BinaryDecisionDiagram& bdd() const { return *bdd_; }
143	
144	  SaturatingBddEvaluator& evaluator() const { return *evaluator_; }
145	
146	  // Returns the BDD node associated with the given bit, if there is one;
147	  // otherwise returns std::nullopt.
148	  std::optional<BddNodeIndex> GetBddNode(
149	      const TreeBitLocation& location) const {
150	    std::optional<SharedBddTree> info = GetInfo(location.node());
151	    if (!info.has_value()) {
152	      return std::nullopt;
153	    }
154	    CHECK_GT(info->Get(location.tree_index()).size(), location.bit_index())
155	        << location;
156	    SaturatingBddNodeIndex node =
157	        info->Get(location.tree_index()).at(location.bit_index());
158	    if (std::holds_alternative<TooManyPaths>(node)) {
159	      return std::nullopt;
160	    }
161	    return std::get<BddNodeIndex>(node);
162	  }
163	
164	  std::optional<BddNodeIndex> GetBddNodeOrVariable(
165	      const TreeBitLocation& location) const {
166	    std::optional<SharedBddTree> info = GetInfo(location.node());
167	    if (!info.has_value()) {
168	      return std::nullopt;
169	    }
170	    SaturatingBddNodeIndex node =
171	        info->Get(location.tree_index()).at(location.bit_index());
172	    if (std::holds_alternative<TooManyPaths>(node)) {
173	      return GetVariableFor(location);
174	    }
175	    return std::get<BddNodeIndex>(node);
176	  }
177	
178	  std::optional<TreeBitLocation> GetTreeBitLocation(
179	      BddNodeIndex bdd_node) const;
180	
181	 protected:
182	  BddTree ComputeInfo(
183	      Node* node,
184	      absl::Span<const BddTree* const> operand_infos) const override;
185	
186	  absl::Status MergeWithGiven(BddVector& info,
187	                              const BddVector& given) const override;
188	
189	  absl::Status PerformGarbageCollection() override;
190	
191	 private:
192	  class AssumingQueryEngine;
193	
194	  std::optional<SharedLeafTypeTree<TernaryVector>> GetTernary(
195	      Node* node, std::optional<BddNodeIndex> assumption) const;
196	
197	  bool AtMostOneTrue(absl::Span<TreeBitLocation const> bits,
198	                     std::optional<BddNodeIndex> assumption) const;
199	  bool AtLeastOneTrue(absl::Span<TreeBitLocation const> bits,
200	                      std::optional<BddNodeIndex> assumption) const;
201	  std::optional<Bits> ImpliedNodeValue(
202	      absl::Span<const std::pair<TreeBitLocation, bool>> predicate_bit_values,
203	      Node* node, std::optional<BddNodeIndex> assumption) const;
204	  std::optional<TernaryVector> ImpliedNodeTernary(
205	      absl::Span<const std::pair<TreeBitLocation, bool>> predicate_bit_values,
206	      Node* node, std::optional<BddNodeIndex> assumption) const;
207	  bool KnownEquals(const TreeBitLocation& a, const TreeBitLocation& b,
208	                   std::optional<BddNodeIndex> assumption) const;
209	  bool KnownNotEquals(const TreeBitLocation& a, const TreeBitLocation& b,
210	                      std::optional<BddNodeIndex> assumption) const;
211	
212	  bool IsKnown(const TreeBitLocation& bit,
213	               std::optional<BddNodeIndex> assumption) const;
214	  std::optional<bool> KnownValue(const TreeBitLocation& bit,
215	                                 std::optional<BddNodeIndex> assumption) const;
216	  std::optional<Value> KnownValue(Node* node,
217	                                  std::optional<BddNodeIndex> assumption) const;
218	
219	  bool IsAllZeros(Node* n, std::optional<BddNodeIndex> assumption) const;
220	  bool IsAllOnes(Node* n, std::optional<BddNodeIndex> assumption) const;
221	  bool IsFullyKnown(Node* n, std::optional<BddNodeIndex> assumption) const;
222	
223	  // A implies B  <=>  !(A && !B)
224	  bool Implies(const BddNodeIndex& a, const BddNodeIndex& b) const;
225	
226	  // Returns true if the expression of the given BDD node exceeds the path
227	  // limit.
228	  // TODO(meheff): This should be part of the BDD itself where a query can be
229	  // performed and the BDD method returns a union of path limit exceeded or
230	  // the result of the query.
231	  bool ExceedsPathLimit(SaturatingBddNodeIndex node) const {
232	    if (path_limit_ <= 0) {
233	      return false;
234	    }
235	    if (HasTooManyPaths(node)) {
236	      return true;
237	    }
238	    return bdd().path_count(std::get<BddNodeIndex>(node)) > path_limit_;
239	  }
240	
241	  // The maximum number of paths in expression in the BDD before truncating.
242	  int64_t path_limit_;
243	
244	  std::optional<std::function<bool(const Node*)>> node_filter_;
245	
246	  std::unique_ptr<BinaryDecisionDiagram> bdd_;
247	  std::unique_ptr<SaturatingBddEvaluator> evaluator_;
248	
249	  // A map from bit locations to BDD variables; used when the BDD is saturated
250	  // to avoid creating new variables for the same bit.
251	  mutable absl::flat_hash_map<TreeBitLocation, BddNodeIndex> bit_variables_;
252	  BddNodeIndex GetVariableFor(TreeBitLocation location) const;
253	
254	  // A map from node IDs to BDD variables used to represent fully-unknown
255	  // values; used to avoid creating new variables for the same node.
256	  mutable absl::flat_hash_map<NodeRef, std::unique_ptr<BddTree>>
257	      node_variables_;
258	  BddTreeView GetVariablesFor(NodeRef node) const;
259	
260	  // A reverse map from BDD variables to bit locations
261	  mutable absl::flat_hash_map<BddNodeIndex, TreeBitLocation> bdd_to_bit_locs_;
262	};
263	
264	}  // namespace xls
265	
266	#endif  // XLS_PASSES_BDD_QUERY_ENGINE_H_
