34	namespace xls {
35	
36	// This type represents a set of intervals.
37	class IntervalSet {
38	 public:
39	  // Create an empty `IntervalSet` with a `BitCount()` of -1. Every method in
40	  // this class fails if called on an `IntervalSet` with bit count -1, so you
41	  // must assign to a default constructed interval set before calling any method
42	  // on it.
43	  IntervalSet() : is_normalized_(true), bit_count_(-1) {}
44	
45	  // Returns an interval set of all the positive intervals of this set.
46	  IntervalSet PositiveIntervals(bool with_zero = true) const;
47	
48	  // Returns an interval set of the absolute values of all the negative
49	  // intervals of this set. The resulting set has the same bit-count as the
50	  // current set.
51	  IntervalSet NegativeAbsoluteIntervals() const;
52	
53	  // Create an empty `IntervalSet` with the given bit count.
54	  explicit IntervalSet(int64_t bit_count)
55	      : is_normalized_(true), bit_count_(bit_count) {}
56	
57	  // Returns true if the intersection of the two interval sets would be empty
58	  // (without constructing the intersection).
59	  static bool Disjoint(const IntervalSet& lhs, const IntervalSet& rhs);
60	
61	  // Returns an interval set that covers every bit pattern with the given width.
62	  static IntervalSet Maximal(int64_t bit_count);
63	
64	  // Returns an interval set that covers every bit pattern except zero with the
65	  // given width.
66	  static IntervalSet NonZero(int64_t bit_count);
67	
68	  // Returns an interval set that covers exactly the given bit pattern.
69	  static IntervalSet Precise(const Bits& bits);
70	
71	  // Returns an interval set that covers every bit pattern except the given bit
72	  // pattern.
73	  static IntervalSet Punctured(const Bits& bits);
74	
75	  // Returns the number of intervals in the set.
76	  // Does not check for normalization, as this function can be used to check if
77	  // normalization is required (e.g.: to prevent blowup in memory usage while
78	  // building a large set of intervals).
79	  int64_t NumberOfIntervals() const { return intervals_.size(); }
80	
81	  // Returns the number of intervals in the set assuming that there is a cut
82	  // between INT_MAX and INT_MIN. This is either exactly NumberOfIntervals() or
83	  // one more than it.
84	  int64_t NumberOfSignedIntervals() const {
85	    if (Covers(Bits::MaxSigned(BitCount())) &&
86	        Covers(Bits::MinSigned(BitCount()))) {
87	      return NumberOfIntervals() + 1;
88	    }
89	    return NumberOfIntervals();
90	  }
91	
92	  // Get all the intervals contained within this interval set.
93	  // The set must be normalized prior to calling this.
94	  absl::Span<const Interval> Intervals() const& {
95	    CHECK(is_normalized_);
96	    return intervals_;
97	  }
98	
99	  std::vector<Interval> Intervals() && {
100	    CHECK(is_normalized_);
101	    return intervals_;
102	  }
103	
104	  class SignedIntervalIterator {
105	   public:
106	    using difference_type = std::ptrdiff_t;
107	    using value_type = const Interval&;
108	
109	    SignedIntervalIterator(SignedIntervalIterator&&) = default;
110	    SignedIntervalIterator(const SignedIntervalIterator&) = default;
111	    SignedIntervalIterator& operator=(SignedIntervalIterator&&) = default;
112	    SignedIntervalIterator& operator=(const SignedIntervalIterator&) = default;
113	
114	    const Interval& operator*() const;
115	    SignedIntervalIterator& operator++();
116	    SignedIntervalIterator operator++(int) {
117	      SignedIntervalIterator tmp = *this;
118	      ++*this;
119	      return tmp;
120	    }
121	
122	    bool operator==(const SignedIntervalIterator& o) const {
123	      if (InSplit() && o.InSplit() && in_negatives_ != o.in_negatives_) {
124	        return false;
125	      }
126	      return cur_ == o.cur_;
127	    }
128	
129	   private:
130	    explicit SignedIntervalIterator(
131	        absl::Span<const Interval>::const_iterator cur,
132	        absl::Span<const Interval>::const_iterator end, bool in_negatives)
133	        : cur_(cur), end_(end), in_negatives_(in_negatives) {}
134	    bool InSplit() const;
135	
136	    absl::Span<const Interval>::const_iterator cur_;
137	    absl::Span<const Interval>::const_iterator end_;
138	
139	    // If this is 'InSplit' what side of it we are on.
140	    bool in_negatives_;
141	
142	    // Holder for the split interval.
143	    mutable std::optional<Interval> sign_swap_interval_;
144	
145	    friend class IntervalSet;
146	  };
147	
148	  // Get all the intervals contained in the interval_set. The set must be
149	  // normalized prior to calling this. The iteration order is all positive
150	  // intervals followed by all negative intervals. Every interval will contain
151	  // only positive or negative numbers.
152	  xabsl::iterator_range<SignedIntervalIterator> SignedIntervals() const;
153	
154	  // A lazy iterator of the bits values in this interval set.
155	  class ValuesIterator {
156	   public:
157	    using difference_type = std::ptrdiff_t;
158	    using value_type = Interval::ValuesIterator::value_type;
159	    using reference = Interval::ValuesIterator::reference;
160	    using pointer = Interval::ValuesIterator::pointer;
161	    using iterator_category = std::forward_iterator_tag;
162	
163	    ValuesIterator(ValuesIterator&&) = default;
164	    ValuesIterator(const ValuesIterator&) = default;
165	    ValuesIterator& operator=(ValuesIterator&&) = default;
166	    ValuesIterator& operator=(const ValuesIterator&) = default;
167	
168	    const Bits& operator*() const { return *cur_value_; }
169	    const Bits* operator->() const { return cur_value_.operator->(); }
170	    ValuesIterator& operator++() {
171	      CHECK(cur_interval_ != end_interval_) << "Incr after end!";
172	      CHECK(cur_value_ != cur_end_) << "Incr after end val!";
173	      ++cur_value_;
174	      if (cur_value_ == cur_end_) {
175	        ++cur_interval_;
176	        if (cur_interval_ != end_interval_) {
177	          cur_value_ = cur_interval_->begin();
178	          cur_end_ = cur_interval_->end();
179	        }
180	      }
181	      return *this;
182	    }
183	    ValuesIterator operator++(int) {
184	      ValuesIterator tmp = *this;
185	      ++*this;
186	      return tmp;
187	    }
188	
189	    template <typename Sink>
190	    friend void AbslStringify(Sink& sink, const ValuesIterator& it) {
191	      if (it.cur_interval_ == it.end_interval_) {
192	        absl::Format(&sink, "END");
193	      } else {
194	        absl::Format(&sink, "%v", *it);
195	      }
196	    }
197	
198	    bool operator==(const ValuesIterator& o) const {
199	      return (cur_interval_ == o.cur_interval_ &&
200	              cur_interval_ == end_interval_) ||
201	             (cur_interval_ == o.cur_interval_ && cur_value_ == o.cur_value_);
202	    }
203	
204	   private:
205	    explicit ValuesIterator(absl::Span<const Interval>::const_iterator cur,
206	                            absl::Span<const Interval>::const_iterator end,
207	                            Interval::ValuesIterator&& cur_value,
208	                            Interval::ValuesIterator&& cur_end)
209	        : cur_interval_(cur),
210	          end_interval_(end),
211	          cur_value_(std::move(cur_value)),
212	          cur_end_(std::move(cur_end)) {}
213	    bool InSplit() const;
214	
215	    absl::Span<const Interval>::const_iterator cur_interval_;
216	    absl::Span<const Interval>::const_iterator end_interval_;
217	    Interval::ValuesIterator cur_value_;
218	    Interval::ValuesIterator cur_end_;
219	
220	    friend class IntervalSet;
221	  };
222	  // Get all the values contained in the interval_set. The set must be
223	  // normalized prior to calling this. The iteration order is unsigned values
224	  // from the lowest to the highest.
225	  xabsl::iterator_range<ValuesIterator> Values() const {
226	    CHECK(is_normalized_);
227	    if (intervals_.empty()) {
228	      return xabsl::make_range(
229	          ValuesIterator(Intervals().begin(), Intervals().end(),
230	                         Interval::ValuesIterator::None(),
231	                         Interval::ValuesIterator::None()),
232	          ValuesIterator(Intervals().begin(), Intervals().end(),
233	                         Interval::ValuesIterator::None(),
234	                         Interval::ValuesIterator::None()));
235	    }
236	    return xabsl::make_range(
237	        ValuesIterator(Intervals().begin(), Intervals().end(),
238	                       Intervals().front().begin(), Intervals().front().end()),
239	        ValuesIterator(Intervals().end(), Intervals().end(),
240	                       Intervals().back().end(), Intervals().back().end()));
241	  }
242	
243	  // Returns the `BitCount()` of all intervals in the interval set.
244	  int64_t BitCount() const {
245	    CHECK_GE(bit_count_, 0);
246	    return bit_count_;
247	  }
248	
249	  // Add an interval to this interval set.
250	  void AddInterval(const Interval& interval) {
251	    is_normalized_ = false;
252	    CHECK_EQ(BitCount(), interval.BitCount());
253	    intervals_.push_back(interval);
254	  }
255	
256	  // Move-version of `AddInterval`.
257	  void AddInterval(Interval&& interval) {
258	    is_normalized_ = false;
259	    CHECK_EQ(BitCount(), interval.BitCount());
260	    intervals_.push_back(std::move(interval));
261	  }
262	
263	  // Modify the set of intervals in this to be exactly the given set.
264	  // If the set of intervals is empty, then the `BitCount()` is set to -1.
265	  // Otherwise, the `BitCount()` is set to the `BitCount()` of the
266	  // given intervals.
267	  void SetIntervals(absl::Span<Interval const> intervals);
268	
269	  // Normalize the set of intervals so that the following statements are true:
270	  //
271	  // 1. The union of the set of points contained within all intervals after
272	  //    normalization is the same as that before normalization
273	  //    (i.e.: normalization does not affect the smeantics of a set of
274	  //    intervals).
275	  // 2. After normalization, the set contains no improper intervals.
276	  // 3. After normalization, no two intervals in the set will overlap or abut.
277	  // 4. After normalization, the result of a call to `Intervals()` will be
278	  //    sorted in lexicographic order (with the underlying ordering given by
279	  //    interpreting each `Bits` as an unsigned integer).
280	  // 5. The result of a call to `Intervals()` has the smallest possible size
281	  //    of any set of intervals representing the same set of points that
282	  //    contains no improper intervals (hence the name "normalization").
283	  void Normalize();
284	
285	  // Return the smallest single proper interval that contains all points in this
286	  // interval set. If the set of points is empty, returns `std::nullopt`.
287	  std::optional<Interval> ConvexHull() const;
288	
289	  // Returns an `IntervalSet` the bounds of which have been zero-extended to the
290	  // given bit width.
291	  // CHECK fails if the bit width is less than the current `BitCount`.
292	  IntervalSet ZeroExtend(int64_t bit_width) const;
293	
294	  // Returns a normalized set of intervals comprising the union of the two given
295	  // interval sets.
296	  static IntervalSet Combine(const IntervalSet& lhs, const IntervalSet& rhs);
297	
298	  // Returns a normalized set of intervals comprising the intersection of the
299	  // two given interval sets.
300	  static IntervalSet Intersect(const IntervalSet& lhs, const IntervalSet& rhs);
301	
302	  // Returns the normalized set of intervals comprising the complement of the
303	  // given interval set.
304	  static IntervalSet Complement(const IntervalSet& set);
305	
306	  static IntervalSet Of(absl::Span<Interval const> intervals);
307	
308	  // Returns an interval set from already proper & sorted intervals that are
309	  // neither overlapping nor abutting; results are undefined if this
310	  // precondition is not met.
311	  //
312	  // This is fast, but doesn't do any normalization of its own. It's the
313	  // caller's responsibility to ensure the preconditions are met; otherwise,
314	  // bad things will happen (e.g.: crashes, incorrect results, etc.).
315	  static IntervalSet UnsafeFromNormalized(int64_t bit_count,
316	                                          std::vector<Interval> intervals);
317	
318	  // Returns the number of points covered by the intervals in this interval set,
319	  // if that is expressible as an `int64_t`. Otherwise, returns `std::nullopt`.
320	  // CHECK fails if the interval set is not normalized.
321	  std::optional<int64_t> Size() const;
322	
323	  // If all the intervals in this interval set were put next to each other and
324	  // treated as a map from `[0, Size() - 1]` to `Bits`, apply this mapping to
325	  // the given integer. Returns `std::nullopt` iff the given integer is out of
326	  // range for this mapping. The returned `Bits` has bitwidth equal to that of
327	  // this interval set.
328	  //
329	  // CHECK fails if this interval set is not normalized, or if the given `index`
330	  // has bitwidth not equal to the bitwidth of this interval set.
331	  //
332	  // For example, if the interval set was `{[2, 3], [5, 7]}`, then this method
333	  // would be like indexing the array `[2, 3, 5, 6, 7]`.
334	  std::optional<Bits> Index(const Bits& index) const;
335	
336	  // Do any of the values within the interval ranges when bit mask with the
337	  // given value produce a non-zero result?
338	  //
339	  // In other words, `intervals.IsTrueWhenMaskWith(m)` is the same as `there
340	  // exists a value x contained in the interval ranges such that or_reduce(x &
341	  // m) is true`.
342	  //
343	  // For example, `intervals.IsTrueWhenMaskWith(4)` where intervals is the set
344	  // `{[2, 3], [5, 7]}`, the result would return true, since the values 4, 5, 6
345	  // and 7 bit masked with 4 returns true. However, if intervals is the set
346	  // `{[2, 3]}`, the result would return false, since no values bit masked with
347	  // 4 returns true.
348	  bool IsTrueWhenMaskWith(const Bits& value) const;
349	
350	  // Do any of the intervals cover the given point?
351	  bool Covers(const Bits& bits) const;
352	
353	  // Do any of the intervals cover zero?
354	  bool CoversZero() const { return Covers(UBits(0, BitCount())); }
355	
356	  // Do any of the intervals cover one?
357	  bool CoversOne() const { return Covers(UBits(1, BitCount())); }
358	
359	  // Do any of the intervals cover `Bits::AllOnes(BitCount())`?
360	  bool CoversMax() const { return Covers(Bits::AllOnes(BitCount())); }
361	
362	  // Do the intervals only cover one point?
363	  bool IsPrecise() const;
364	
365	  // Returns the unique member of the interval set if the interval set is
366	  // precise. If the interval is not precise, returns std::nullopt.
367	  // CHECK fails if the interval set is not normalized.
368	  std::optional<Bits> GetPreciseValue() const;
369	
370	  // Do the intervals cover every point?
371	  // `Normalize()` must be called prior to calling this method.
372	  bool IsMaximal() const;
373	
374	  // Returns true iff this set of intervals is normalized.
375	  bool IsNormalized() const;
376	
377	  // Returns true iff this set of intervals is empty.
378	  bool IsEmpty() const;
379	
380	  // Returns the inclusive lower/upper bound of the interval set.
381	  std::optional<Bits> LowerBound() const;
382	  std::optional<Bits> UpperBound() const;
383	
384	  // Print this set of intervals as a string.
385	  std::string ToString() const;
386	
387	  friend bool operator==(IntervalSet lhs, IntervalSet rhs) {
388	    lhs.Normalize();
389	    rhs.Normalize();
390	    if (lhs.bit_count_ != rhs.bit_count_) {
391	      return false;
392	    }
393	    return lhs.intervals_ == rhs.intervals_;
394	  }
395	
396	  template <typename H>
397	  friend H AbslHashValue(H h, const IntervalSet& set) {
398	    return H::combine(std::move(h), set.bit_count_, set.intervals_);
399	  }
400	
401	  template <typename Sink>
402	  friend void AbslStringify(Sink& sink, const IntervalSet& set) {
403	    absl::Format(&sink, "%s", set.ToString());
404	  }
405	
406	  template <typename Sink>
407	  friend void FuzzTestPrintSourceCode(Sink& sink, const IntervalSet& is) {
408	    absl::Format(&sink, "IntervalSet::Of({");
409	    bool first = true;
410	    for (const Interval& interval : is.Intervals()) {
411	      if (!first) {
412	        absl::Format(&sink, ", ");
413	      }
414	      FuzzTestPrintSourceCode(sink, interval);
415	      first = false;
416	    }
417	    absl::Format(&sink, "})");
418	  }
419	
420	  // Actually check exhaustively for normalization instead of trusting the flag.
421	  absl::Status CheckIsNormalizedForTesting() const;
422	
423	 private:
424	  IntervalSet(std::in_place_t in_place, bool is_normalized, int64_t bit_count,
425	              std::vector<Interval> intervals)
426	      : is_normalized_(is_normalized),
427	        bit_count_(bit_count),
428	        intervals_(intervals) {}
429	
430	  bool is_normalized_;
431	  int64_t bit_count_;
432	  std::vector<Interval> intervals_;
433	};
434	
435	inline std::ostream& operator<<(std::ostream& os,
436	                                const IntervalSet& interval_set) {
437	  os << interval_set.ToString();
438	  return os;
439	}
440	
441	}  // namespace xls
442	
443	#endif  // XLS_IR_INTERVAL_SET_H_
