34	namespace xls {
35	
36	namespace internal {
37	
38	// A helper to represent a query engine that can be cached in some way. This
39	// should only be used as an internal implementation detail in the context
40	// classes or as an ABC for LazyQueryEngine. Note that
41	class CacheableQueryEngine : public QueryEngine {
42	 public:
43	  // Perform a GC of information stored in the query engine. Use best-effort to
44	  // guess whether a gc is even required and skip it if it looks unlikely to do
45	  // anything.
46	  virtual absl::Status MaybePerformGarbageCollection() = 0;
47	  // Perform a GC of internal qe information. Do this regardless of whether it
48	  // seems likely any garbage is present to be collected.
49	  virtual absl::Status ForcePerformGarbageCollection() = 0;
50	};
51	}  // namespace internal
52	
53	// A base class for query engines that can be lazily populated; implements an
54	// invalidating/"re-validating" cache for any analysis that depends only on the
55	// transitive inputs to a node.
56	//
57	// Derived classes must implement:
58	// - `ComputeInfo`: called when a node's information needs to be recalculated,
59	//    and
60	// - `MergeWithGiven`: called to merge computed information with given
61	//    information,
62	// and then must implement all pure-virtual methods of `QueryEngine`, but may
63	// use `QueryInfo` to retrieve the information for a node.
64	//
65	// This abstracts away the details of the information being stored and the ways
66	// it's used to answer queries, allowing this class to focus entirely on the
67	// caching logic.
68	//
69	// This class implements a cache with a simple state machine; each node has
70	// either no recorded information (kUnknown), information that may be
71	// out-of-date (kUnverified), information that is valid if all inputs prove to
72	// be up-to-date (kInputsUnverified), or information that is known to be current
73	// & correct (kKnown).
74	//
75	// On populating with a FunctionBase, this class listens for change events. When
76	// a node changes, we mark its information as potentially out-of-date
77	// (kUnverified), and update all transitive users that are in state kKnown to
78	// kInputsUnverified. (In some exceptional circumstances, we can guess a node's
79	// value and mark it kUnverified if this would allow us to keep other nodes
80	// kInputsUnverified.)
81	//
82	// When a node `n` is queried, we query for the information for all of its
83	// operands, and then re-compute the information for `n` if absent or
84	// unverified. If `n` was in state kUnverified & this does change its associated
85	// information, we mark any direct users that were in state kInputsUnverified as
86	// kUnverified, since their inputs have changed.
87	//
88	// NOTE: If `n` is in state kInputsUnverified after we queried all of its
89	//       operands, then their values did not change, so we have verified that
90	//       `n`'s information is up-to-date without having to recompute it! This is
91	//       the main advantage of this cache over a more typical invalidating
92	//       cache.
93	template <typename Info>
94	class LazyQueryEngine : public internal::CacheableQueryEngine {
95	 protected:
96	  class QueryEngineNodeInfo : public LazyNodeInfo<Info> {
97	   public:
98	    using typename LazyNodeInfo<Info>::CacheState;
99	    explicit QueryEngineNodeInfo(LazyQueryEngine<Info>* owner)
100	        : LazyNodeInfo<Info>(DagCacheInvalidateDirection::kInvalidatesUsers),
101	          owner_(owner) {}
102	    QueryEngineNodeInfo(const QueryEngineNodeInfo&) = default;
103	    QueryEngineNodeInfo(QueryEngineNodeInfo&&) = default;
104	    QueryEngineNodeInfo& operator=(const QueryEngineNodeInfo&) = default;
105	    QueryEngineNodeInfo& operator=(QueryEngineNodeInfo&&) = default;
106	
107	    QueryEngineNodeInfo WithOwner(LazyQueryEngine<Info>* owner) const& {
108	      QueryEngineNodeInfo info(*this);
109	      info.owner_ = owner;
110	      return info;
111	    }
112	
113	    QueryEngineNodeInfo TakeOwner(LazyQueryEngine<Info>* owner) && {
114	      QueryEngineNodeInfo info(std::move(*this));
115	      info.owner_ = owner;
116	      return info;
117	    }
118	
119	    // This is likely to render some parts of the query engine obsolete. Just
120	    // mark a GC as requested.
121	    void NodeDeleted(Node* node) override {
122	      owner_->MarkGcNeeded();
123	      LazyNodeInfo<Info>::NodeDeleted(node);
124	    }
125	
126	    // This is likely to render some parts of the query engine obsolete. Just
127	    // mark a GC as requested.
128	    void OperandRemoved(Node* node, Node* old_operand) override {
129	      owner_->MarkGcNeeded();
130	      LazyNodeInfo<Info>::OperandRemoved(node, old_operand);
131	    }
132	
133	    // Allow direct access to the cache info to implement gc.
134	    using LazyNodeInfo<Info>::cache;
135	
136	   protected:
137	    LeafTypeTree<Info> ComputeInfo(
138	        Node* node,
139	        absl::Span<const LeafTypeTree<Info>* const> operand_infos) const final;
140	
141	    absl::Status MergeWithGiven(Info& info, const Info& given) const final;
142	
143	   private:
144	    LazyQueryEngine<Info>* owner_;
145	  };
146	
147	 public:
148	  LazyQueryEngine<Info>() : info_(this) {}
149	  ~LazyQueryEngine() override = default;
150	
151	  LazyQueryEngine(const LazyQueryEngine<Info>& other)
152	      : info_(other.info_.WithOwner(this)) {}
153	  LazyQueryEngine& operator=(const LazyQueryEngine<Info>& other) {
154	    info_ = other.info_.WithOwner(this);
155	    return *this;
156	  }
157	  LazyQueryEngine(LazyQueryEngine<Info>&& other)
158	      : info_(std::move(other).info_.TakeOwner(this)) {}
159	  LazyQueryEngine& operator=(LazyQueryEngine<Info>&& other) {
160	    info_ = std::move(other).info_.TakeOwner(this);
161	    return *this;
162	  }
163	
164	  absl::StatusOr<ReachedFixpoint> PopulateWithGivens(
165	      FunctionBase* f, absl::flat_hash_map<Node*, LeafTypeTree<Info>> givens) {
166	    return info_.AttachWithGivens(f, std::move(givens));
167	  }
168	  absl::StatusOr<ReachedFixpoint> Populate(FunctionBase* f) override {
169	    return info_.Attach(f);
170	  }
171	
172	  bool IsTracked(Node* node) const override {
173	    return node->function_base() == info_.bound_function();
174	  }
175	
176	  // Check that the query engine is consistent. Note that Forced values are
177	  // always considered consistent.
178	  absl::Status CheckConsistency() const override {
179	    return info_.CheckCacheConsistency();
180	  }
181	
182	  // Access to the underlying data store for this query engine. Use this to
183	  // directly add givens if required.
184	  LazyNodeInfo<Info>& info() { return qe_info(); }
185	
186	  // Access to the underlying data store for this query engine. Use this to
187	  // directly add givens if required.
188	  const LazyNodeInfo<Info>& info() const { return qe_info(); }
189	
190	  std::optional<SharedLeafTypeTree<Info>> GetInfo(Node* node) const {
191	    return info_.GetInfo(node);
192	  }
193	
194	  // Eagerly computes the values for all nodes in the function that do not have
195	  // known values. This is expensive and should only be used for testing and
196	  // measurement.
197	  absl::Status EagerlyPopulate(FunctionBase* f) {
198	    return info_.EagerlyPopulate(f);
199	  }
200	
201	  void ForceRecompute(Node* node) { info_.ForceRecompute(node); }
202	
203	  // Helpers for adding/removing givens.
204	  absl::StatusOr<ReachedFixpoint> AddGiven(Node* node,
205	                                           LeafTypeTree<Info> given_ltt) {
206	    return info_.AddGiven(node, std::move(given_ltt));
207	  }
208	  absl::StatusOr<ReachedFixpoint> ReplaceGiven(Node* node,
209	                                               LeafTypeTree<Info> given_ltt) {
210	    return info_.ReplaceGiven(node, std::move(given_ltt));
211	  }
212	  ReachedFixpoint RemoveGiven(Node* node) { return info_.RemoveGiven(node); }
213	
214	  // Set the node to a single immutable forced value.
215	  //
216	  // This is different from Givens since it is not combined with the calculated
217	  // values from earlier in the tree but instead considered a-priori known.
218	  //
219	  // Note that any forced value may not have a given associated with it as the
220	  // given value will be ignored.
221	  //
222	  // Care should be taken when using this since existing information is utterly
223	  // ignored. In general AddGiven is a better choice.
224	  absl::StatusOr<ReachedFixpoint> SetForced(Node* node,
225	                                            LeafTypeTree<Info> forced_ltt) {
226	    return info_.SetForced(node, std::move(forced_ltt));
227	  }
228	  // Removed forced information.
229	  absl::StatusOr<ReachedFixpoint> RemoveForced(Node* node) {
230	    return info_.RemoveForced(node);
231	  }
232	
233	  absl::Status ForcePerformGarbageCollection() override {
234	    needs_gc_ = false;
235	    return PerformGarbageCollection();
236	  }
237	
238	  absl::Status MaybePerformGarbageCollection() override {
239	    if (needs_gc_) {
240	      needs_gc_ = false;
241	      return PerformGarbageCollection();
242	    }
243	    return absl::OkStatus();
244	  }
245	
246	 protected:
247	  virtual LeafTypeTree<Info> ComputeInfo(
248	      Node* node,
249	      absl::Span<const LeafTypeTree<Info>* const> operand_infos) const = 0;
250	
251	  virtual absl::Status MergeWithGiven(Info& info, const Info& given) const = 0;
252	
253	  // Actually perform GC and remove unneeded data and minimize memory use as
254	  // appropriate for the query engine. By default does nothing. This is only
255	  // called if something has changed in the query engine since the last call.
256	  //
257	  // Note in general query engines should simply clean up garbage as they go.
258	  // This is only used for cases where that is not possible and a more involved
259	  // scan of values is required to determine dead information (eg Cleaning up
260	  // bdd nodes). Most query engines should not override this function.
261	  virtual absl::Status PerformGarbageCollection() { return absl::OkStatus(); }
262	  void MarkGcNeeded() { needs_gc_ = true; }
263	
264	  // For MarkGcNeeded.
265	  friend class QueryEngineNodeInfo;
266	
267	  // Get node-info as the internal QueryEngineNodeInfo to allow for more
268	  // visibility.
269	  QueryEngineNodeInfo& qe_info() { return info_; }
270	  // Get node-info as the internal QueryEngineNodeInfo to allow for more
271	  // visibility.
272	  const QueryEngineNodeInfo& qe_info() const { return info_; }
273	
274	 private:
275	  QueryEngineNodeInfo info_;
276	
277	  // Has any changes occurred that seem likely to have invalidated parts of the
278	  // query engine, allowing data to be gc'd.
279	  bool needs_gc_ = false;
280	};
281	
282	template <typename Info>
283	absl::Status LazyQueryEngine<Info>::QueryEngineNodeInfo::MergeWithGiven(
284	    Info& info, const Info& given) const {
285	  // We are potentially invalidating things. Request a gc later.
286	  owner_->MarkGcNeeded();
287	  return owner_->MergeWithGiven(info, given);
288	}
289	
290	template <typename Info>
291	LeafTypeTree<Info> LazyQueryEngine<Info>::QueryEngineNodeInfo::ComputeInfo(
292	    Node* node,
293	    absl::Span<const LeafTypeTree<Info>* const> operand_infos) const {
294	  // We are potentially invalidating things. Request a gc later.
295	  owner_->MarkGcNeeded();
296	  return owner_->ComputeInfo(node, operand_infos);
297	}
298	
299	}  // namespace xls
300	
301	#endif  // XLS_PASSES_LAZY_QUERY_ENGINE_H_
