186	inline TernaryValue And(const TernaryValue& a, const TernaryValue& b) {
187	  // Truth table:
188	  //              rhs
189	  //      & |  0   1   X
190	  //      --+------------
191	  // lhs  0 |  0   0   0
192	  //      1 |  0   1   X
193	  //      X |  0   X   X
194	  if (a == TernaryValue::kKnownZero || b == TernaryValue::kKnownZero) {
195	    return TernaryValue::kKnownZero;
196	  }
197	  if (a == TernaryValue::kKnownOne && b == TernaryValue::kKnownOne) {
198	    return TernaryValue::kKnownOne;
199	  }
200	  return TernaryValue::kUnknown;
201	}
202	inline TernaryVector And(TernarySpan a, TernarySpan b) {
203	  CHECK_EQ(a.size(), b.size());
204	  TernaryVector result(a.size());
205	  for (int64_t i = 0; i < a.size(); ++i) {
206	    result[i] = And(a[i], b[i]);
207	  }
208	  return result;
209	}
210	
211	inline TernaryValue Or(const TernaryValue& a, const TernaryValue& b) {
212	  // Truth table:
213	  //              rhs
214	  //      | |  0   1   X
215	  //      --+------------
216	  // lhs  0 |  0   1   X
217	  //      1 |  1   1   1
218	  //      X |  X   1   X
219	  if (a == TernaryValue::kKnownOne || b == TernaryValue::kKnownOne) {
220	    return TernaryValue::kKnownOne;
221	  }
222	  if (a == TernaryValue::kKnownZero && b == TernaryValue::kKnownZero) {
223	    return TernaryValue::kKnownZero;
224	  }
225	  return TernaryValue::kUnknown;
226	}
227	inline TernaryVector Or(TernarySpan a, TernarySpan b) {
228	  CHECK_EQ(a.size(), b.size());
229	  TernaryVector result(a.size());
230	  for (int64_t i = 0; i < a.size(); ++i) {
231	    result[i] = Or(a[i], b[i]);
232	  }
233	  return result;
234	}
