236	inline TernaryValue Not(const TernaryValue& a) {
237	  switch (a) {
238	    case TernaryValue::kKnownZero:
239	      return TernaryValue::kKnownOne;
240	    case TernaryValue::kKnownOne:
241	      return TernaryValue::kKnownZero;
242	    case TernaryValue::kUnknown:
243	      return TernaryValue::kUnknown;
244	  }
245	  ABSL_UNREACHABLE();
246	}
247	inline TernaryVector Not(TernarySpan a) {
248	  TernaryVector result;
249	  result.reserve(a.size());
250	  absl::c_transform(a, std::back_inserter(result),
251	                    [](TernaryValue v) { return Not(v); });
252	  return result;
253	}
