255	inline TernaryValue Xor(const TernaryValue& a, const TernaryValue& b) {
256	  // Truth table:
257	  //              rhs
258	  //      | |  0   1   X
259	  //      --+------------
260	  // lhs  0 |  0   1   X
261	  //      1 |  1   0   X
262	  //      X |  X   X   X
263	  if (a == TernaryValue::kUnknown || b == TernaryValue::kUnknown) {
264	    return TernaryValue::kUnknown;
265	  }
266	  return a == b ? TernaryValue::kKnownZero : TernaryValue::kKnownOne;
267	}
268	inline TernaryVector Xor(TernarySpan a, TernarySpan b) {
269	  CHECK_EQ(a.size(), b.size());
270	  TernaryVector result(a.size());
271	  for (int64_t i = 0; i < a.size(); ++i) {
272	    result[i] = Xor(a[i], b[i]);
273	  }
274	  return result;
275	}
