279	// An iterator of possible ternary values.
280	class RealizedTernaryIterator {
281	 public:
282	  using value_type = Bits;
283	  using reference = const Bits&;
284	  using pointer = const Bits*;
285	  using difference_type = std::ptrdiff_t;
286	  using iterator_category = std::forward_iterator_tag;
287	  using iterator_concept = std::forward_iterator_tag;
288	
289	  RealizedTernaryIterator(const RealizedTernaryIterator&) = default;
290	  RealizedTernaryIterator(RealizedTernaryIterator&&) = default;
291	  RealizedTernaryIterator& operator=(const RealizedTernaryIterator&) = default;
292	  RealizedTernaryIterator& operator=(RealizedTernaryIterator&&) = default;
293	  explicit RealizedTernaryIterator() : finished_(true) {}
294	
295	  const Bits& operator*() const {
296	    CHECK(!finished_);
297	    return value_;
298	  }
299	
300	  const Bits* operator->() const { return &**this; }
301	
302	  bool operator==(const RealizedTernaryIterator& o) const {
303	    if (finished_ != o.finished_) {
304	      // One is at the end and the other isn't
305	      return false;
306	    }
307	    if (finished_ && o.finished_) {
308	      return true;
309	    }
310	    return value_ == o.value_;
311	  }
312	
313	  // Pre increment
314	  RealizedTernaryIterator& operator++() {
315	    Advance(1);
316	    return *this;
317	  }
318	
319	  RealizedTernaryIterator& operator+=(int64_t amnt) {
320	    CHECK_GE(amnt, 0);
321	    Advance(amnt);
322	    return *this;
323	  }
324	
325	  RealizedTernaryIterator& operator+=(const Bits& amnt) {
326	    Advance(amnt);
327	    return *this;
328	  }
329	
330	  // Post increment
331	  RealizedTernaryIterator operator++(int) {
332	    RealizedTernaryIterator cpy = *this;
333	    Advance(1);
334	    return cpy;
335	  }
336	
337	  RealizedTernaryIterator operator+(const Bits& v) const {
338	    RealizedTernaryIterator res = *this;
339	    res += v;
340	    return res;
341	  }
342	
343	  RealizedTernaryIterator operator+(int v) const {
344	    RealizedTernaryIterator res = *this;
345	    res += v;
346	    return res;
347	  }
348	
349	  template <typename Sink>
350	  friend void AbslStringify(Sink& sink, const RealizedTernaryIterator& it) {
351	    if (it.finished_) {
352	      absl::Format(&sink, "(ternary-iterator @ end)");
353	    } else {
354	      absl::Format(&sink, "(ternary-iterator @ %s)", it.value_.ToDebugString());
355	    }
356	  }
357	
358	 private:
359	  explicit RealizedTernaryIterator(TernarySpan span)
360	      : finished_(false),
361	        value_(ToKnownBitsValues(span)),
362	        unknown_bit_offsets_(
363	            RealizedTernaryIterator::FindUnknownOffsets(span)) {}
364	
365	  void Advance(int64_t amnt);
366	  void Advance(const Bits& amnt);
367	  static std::vector<int64_t> FindUnknownOffsets(TernarySpan span);
368	
369	  bool finished_;
370	  Bits value_;
371	  std::vector<int64_t> unknown_bit_offsets_;
372	
373	  friend xabsl::iterator_range<RealizedTernaryIterator> AllBitsValues(
374	      TernarySpan span);
375	};
376	
377	// Make an iterator range that enumerates all possible values which match the
378	// given ternary. The values are produced in order from smallest to largest.
379	//
380	// NB To match with bits convention an empty span is considered to have one
381	// (0-bit) value associated with it.
382	inline xabsl::iterator_range<RealizedTernaryIterator> AllBitsValues(
383	    TernarySpan span) {
384	  static_assert(std::forward_iterator<RealizedTernaryIterator>);
385	  return {RealizedTernaryIterator(span), RealizedTernaryIterator()};
386	}
387	
388	// Make an iterator range that enumerates all possible values which match the
389	// given tree of ternaries. The values are produced in order from smallest to
390	// largest at each position, in little-endian order (i.e., the first leaf
391	// changes most often, and the last leaf changes least often).
392	absl::StatusOr<std::vector<Value>> AllValues(
393	    LeafTypeTreeView<TernaryVector> ltt);
394	
395	}  // namespace ternary_ops
396	}  // namespace xls
397	
398	#endif  // XLS_IR_TERNARY_H_
