131	// Returns whether the given op should be included in BDD computations.
132	bool ShouldEvaluate(const Node* node) {
133	  if (!node->GetType()->IsBits()) {
134	    return false;
135	  }
136	  if (node->OpIn(kShiftAndSliceOps)) {
137	    int64_t width = node->BitCountOrDie();
138	    if (node->op() == Op::kDynamicBitSlice) {
139	      width = std::max(width, node->operand(0)->BitCountOrDie());
140	    }
141	    if (width > kMaxBddShiftAndSliceBitWidth) {
142	      return false;
143	    }
144	  }
145	  return !(node->OpIn(kNonAnalyzableOps) || node->OpIn(kMultiplicationOps));
