203	bool BddQueryEngine::AssumingQueryEngine::IsTracked(Node* node) const {
204	  return query_engine_->IsTracked(node);
205	}
206	std::optional<SharedLeafTypeTree<TernaryVector>>
207	BddQueryEngine::AssumingQueryEngine::GetTernary(Node* node) const {
208	  if (!query_engine_->IsTracked(node)) {
209	    return std::nullopt;
210	  }
211	  absl::StatusOr<TernaryTree> ltt = TernaryTree::CreateFromFunction(
212	      node->GetType(),
213	      [&](Type* leaf_type, absl::Span<const int64_t> tree_index)
214	          -> absl::StatusOr<TernaryVector> {
215	        TernaryVector ternary(leaf_type->GetFlatBitCount(),
216	                              TernaryValue::kUnknown);
217	        for (int64_t bit_index = 0; bit_index < leaf_type->GetFlatBitCount();
218	             ++bit_index) {
219	          std::optional<BddNodeIndex> bit = query_engine_->GetBddNode(
220	              TreeBitLocation(node, bit_index, tree_index));
221	          if (!bit.has_value()) {
222	            continue;
223	          }
224	          if (query_engine_->Implies(assumption_, *bit)) {
225	            ternary[bit_index] = TernaryValue::kKnownOne;
226	          } else if (query_engine_->Implies(assumption_,
227	                                            query_engine_->bdd().Not(*bit))) {
228	            ternary[bit_index] = TernaryValue::kKnownZero;
229	          }
230	        }
231	        return ternary;
232	      });
233	  if (!ltt.ok()) {
234	    return std::nullopt;
235	  }
236	  return std::move(ltt).value().AsShared();
237	};
