class BddQueryEngine::AssumingQueryEngine final : public QueryEngine {
 public:
  AssumingQueryEngine(const BddQueryEngine* query_engine,
                      BddNodeIndex assumption)
      : query_engine_(query_engine), assumption_(assumption) {}
